1	export interface WorkspaceConvention {
2	  raw: string;
3	  type: 'filename-case' | 'directory-layout' | 'naming' | 'structural' | 'other';
4	  canonical: string;
5	}
6	
7	export interface WorkspaceAgentFiles {
8	  agentsMd?: string;
9	  workspaceJson?: string;
10	}
11	
12	export interface WorkspaceGitSummary {
13	  nonAgentsCommitCount30Days: number;
14	  filesChangedLast30Days: string[];
15	}
16	
17	export interface WorkspaceHygiene {
18	  score: number;
19	  grade: 'A' | 'B' | 'C' | 'D' | 'F';
20	  failCount: number;
21	  warnCount: number;
22	  scannedAt: string;
23	}
24	
25	export interface WorkspacePackage {
26	  name?: string;
27	  path: string;
28	  agentsMd?: string;
29	  dependencies?: string[];
30	  [key: string]: unknown;
31	}
32	
33	export interface WorkspaceJson {
34	  version: string;
35	  generatedAt?: string;
36	  repository?: string;
37	  topology?: 'single-package' | 'monorepo' | 'polyglot-monorepo';
38	  ciProvider?: 'github-actions' | 'gitlab-ci' | 'circleci' | 'jenkins' | 'none' | 'unknown';
39	  agentFiles?: WorkspaceAgentFiles;
40	  frameworks?: string[];
41	  conventions?: WorkspaceConvention[];
42	  packages?: WorkspacePackage[];
43	  gitSummary?: WorkspaceGitSummary;
44	  hygiene?: WorkspaceHygiene;
45	  metadata?: Record<string, unknown>;
46	  [key: string]: unknown;
47	}
48	
49	// v0.3 types
50	
51	export interface FrameworkEntry {
52	  name: string;
53	  version?: string;
54	  confidence: number;
55	}
56	
57	export interface FileIndexEntry {
58	  fragility?: number;
59	  aiModificationCount?: number;
60	  humanModificationCount?: number;
61	  [key: string]: unknown;
62	}
63	
64	export type IntelligenceState = 'INSUFFICIENT_DATA' | 'OBSERVING' | 'CONFIDENT';
65	
66	export interface WorkspaceJsonV3 {
67	  /**
68	   * Optional mirror of `generated.specVersion` (ADR-004). When present it must
69	   * equal `generated.specVersion`; a document where the two disagree is invalid
70	   * and `validate()` rejects it. Absence means the producer predates this
71	   * profile — it is not a signal, and consumers must not branch on it.
72	   *
73	   * Read the profile from `generated.specVersion`, which remains the primary
74	   * declaration and stays required.
75	   */
76	  version?: '0.3';
77	  manual: {
78	    fragileFiles?: Array<{ path: string; reason?: string }>;
79	    coChangePatterns?: Array<{ files: string[]; note?: string }>;
80	    [key: string]: unknown;
81	  };
82	  generated: {
83	    specVersion: '0.3';
84	    generatedAt: string;
85	    by: { name: string; version: string };
86	    frameworkManifest: FrameworkEntry[];
87	    fileIndex: Record<string, FileIndexEntry>;
88	    topology?: { packageCount?: number; [key: string]: unknown };
89	    warnings?: string[];
90	    [key: string]: unknown;
91	  };
92	  agents: Record<string, unknown>;
93	  health: {
94	    intelligenceState: IntelligenceState;
95	    observationCount: number;
96	    confidence: number;
97	    averageFragility?: number;
98	    fragileFileCount?: number;
99	    [key: string]: unknown;
100	  };
101	}
102	
103	/** What both co-change entry forms carry, whichever form an entry takes. */
104	export interface CoChangeEntryCommon {
105	  /**
106	   * The co-changing pair. **Set semantics: exactly two entries, order NOT
107	   * meaningful** — `files[0]` carries no positional significance and consumers
108	   * must join by set membership, not index. Each entry is a
109	   * repository-root-relative POSIX path (forward slashes, no leading "./").
110	   * Invariant: length === 2 (mirrors schema minItems/maxItems: 2).
111	   */
112	  files: string[];
113	  /**
114	   * The denominator. **Its referent depends on which form the entry takes**, so
115	   * establish the form before reading it — see
116	   * {@link LegacyCoChangeEntry} and {@link ObservationCoChangeEntry}. Values
117	   * must not be compared across the two forms.
118	   */
119	  occurrences: number;
120	}
121	
122	/**
123	 * The pre-amendment entry form: a derived `rate` plus an `occurrences` whose
124	 * meaning was never normatively specified and must not be assumed symmetric.
125	 *
126	 * **Deprecated, and accepted only for the v0.4 transition** so that artifacts
127	 * published before the observation form keep validating. New producers must not
128	 * emit it. Removed at the next document-profile change.
129	 */
130	export interface LegacyCoChangeEntry extends CoChangeEntryCommon {
131	  /** @deprecated Legacy form only. Derive `support / occurrences` instead. */
132	  rate: number;
133	  /** Never present in the legacy form — the two forms are mutually exclusive. */
134	  support?: never;
135	  /**
136	   * `true` = tooling-coupled pair (e.g. lockfile + manifest); consumers skip these.
137	   *
138	   * **Required in this form only.** Every artifact published in the legacy form
139	   * already carries it and that contract is frozen until the form is removed, so
140	   * widening it here would loosen a shape nobody should be emitting. New
141	   * producers do not emit this form at all — see
142	   * {@link ObservationCoChangeEntry.generated} for the three-state reading that
143	   * applies to everything written from now on.
144	   */
145	  generated: boolean;
146	}
147	
148	/**
149	 * The current entry form: raw commit counts, symmetric under swapping the pair,
150	 * with no derived value stored.
151	 */
152	export interface ObservationCoChangeEntry extends CoChangeEntryCommon {
153	  /**
154	   * Distinct qualifying commits in which **both** files changed.
155	   *
156	   * Commits are counted, not file events and not ordered relationships — a
157	   * commit touching either file more than once counts once. Symmetric: swapping
158	   * the two entries of `files` does not change it.
159	   *
160	   * Invariant: `support <= occurrences`, because the commits counted here are a
161	   * subset of the commits `occurrences` counts. JSON Schema cannot compare two
162	   * instance values, so `validate()` enforces this and the packaged schema does
163	   * not.
164	   */
165	  support: number;
166	  /**
167	   * Distinct qualifying commits in which **at least one** of the two files
168	   * changed — the symmetric union denominator. Commits are counted, not file
169	   * events. Symmetric under swapping the pair.
170	   *
171	   * A *qualifying commit* is one inside the analysis boundary declared by the
172	   * producer, reachable from `generated.basisRevision`. The standard does not
173	   * define that boundary; it requires that one boundary is applied identically
174	   * to `support` and `occurrences` in every entry.
175	   *
176	   * **Minimum 1**, enforced by the schema for this form only. A pair whose
177	   * union of qualifying commits is empty was never observed changing at all, so
178	   * no entry may be emitted for it — absence of an entry, not a zero
179	   * denominator, represents an unobserved pair. `support / occurrences` is
180	   * therefore always defined on a conforming artifact, and no reader can derive
181	   * `0/0`, `NaN` or infinity from one. TypeScript cannot express the bound; the
182	   * validator does.
183	   *
184	   * No derived rate, probability, lift or ranking is stored.
185	   */
186	  occurrences: number;
187	  /** Never present in the observation form — the two forms are mutually exclusive. */
188	  rate?: never;
189	  /**
190	   * Whether the pair is tooling-coupled — a lockfile and its manifest, a
191	   * generated file and its source — so that a consumer surfacing real source
192	   * couplings can skip it.
193	   *
194	   * **Optional, and three-state.** Unlike `support` and `occurrences` this is a
195	   * *classification*, not an observation: it cannot be read off the commit
196	   * graph, because it requires a judgement about what a file *is*, and this
197	   * standard specifies no portable deterministic classifier from public
198	   * repository inputs. Read it as:
199	   *
200	   * - `true` — classified as tooling-coupled;
201	   * - `false` — classified as **not** tooling-coupled;
202	   * - **absent** — no classification was performed; the producer asserts
203	   *   nothing.
204	   *
205	   * A reader must not collapse absent into `false`. Doing so converts a
206	   * producer's silence into a positive claim that the pair is a real source
207	   * coupling — the unsupported certainty a required boolean forced, and the
208	   * reason this field is optional. Use `entry.generated === true` to skip and
209	   * `entry.generated === false` to keep; branch separately on `undefined`
210	   * rather than letting it fall through a falsy test.
211	   *
212	   * A producer omits this unless it implements a public, deterministic,
213	   * perturbation-tested classifier. Two producers that classify the same pair
214	   * differently are both conformant, so this is not a comparison surface
215	   * between producers.
216	   */
217	  generated?: boolean;
218	}
219	
220	/**
221	 * A co-change entry in either accepted form. The `?: never` members make an
222	 * entry carrying **both** `rate` and `support` a compile error, mirroring the
223	 * schema's `oneOf`; an entry carrying **neither** fails to satisfy either member.
224	 *
225	 * Narrow with `entry.support !== undefined` before reading observation-form fields.
226	 * An `in` check does NOT discriminate here: the `?: never` members mean both
227	 * union members declare both properties, so `'support' in entry` leaves the
228	 * union intact. Comparing against `undefined` narrows, because the property
229	 * collapses to `undefined` on the other member.
230	 */
231	export type CoChangeEntry = LegacyCoChangeEntry | ObservationCoChangeEntry;
232	
233	export interface FragilityEntry {
234	  file: string;
235	  changeCount: number;
236	  revertCount: number;
237	  /** revertCount / changeCount */
238	  revertRate: number;
239	  /** 0-1 composite score */
240	  fragilityScore: number;
241	  /** true = generated/lock file excluded from analysis */
242	  excluded: boolean;
243	}
244	
245	export interface WorkspaceJsonV4 {
246	  /** Optional mirror of `generated.specVersion` (ADR-004). See {@link WorkspaceJsonV3.version}. */
247	  version?: '0.4';
248	  manual: WorkspaceJsonV3['manual'];
249	  generated: Omit<WorkspaceJsonV3['generated'], 'specVersion'> & {
250	    specVersion: '0.4';
251	    /**
252	     * The revision the `generated` observations were computed from. Declared
253	     * once for the section, never per observation.
254	     *
255	     * **The object-ID contract is scoped to the observation form, not global.**
256	     * Where any `coChange` entry carries `support`, this is required and must be
257	     * a full-length lowercase hexadecimal Git object name — 40 characters for
258	     * SHA-1, 64 for SHA-256 — since a pin that does not name exactly one commit
259	     * permanently cannot be recounted against. Everywhere else the key is
260	     * unconstrained: a legacy artifact may already carry it with any value,
261	     * including a symbolic ref such as `"HEAD"`, and constraining it globally
262	     * would invalidate a document that was valid before this amendment.
263	     *
264	     * A producer emitting the observation form must declare a conforming value
265	     * whenever `coChange` exists at all, **including when the array is empty** —
266	     * a producer-profile obligation, because an empty array gives schema
267	     * validation nothing to discriminate on.
268	     */
269	    basisRevision?: string;
270	    coChange?: CoChangeEntry[];
271	    fragility?: FragilityEntry[];
272	  };
273	  agents: WorkspaceJsonV3['agents'];
274	  health: WorkspaceJsonV3['health'] & {
275	    workflowFragility?: number;
276	    codebaseHealth?: number;
277	    changeVolatility?: number;
278	  };
279	}
280

